// Core1 four-bridge spectra, complete A inputs and every B port permutation.
#include <bits/stdc++.h>
using namespace std;using E=vector<pair<int,int>>;int c;int hs[3]={3,5,9};vector<array<int,4>>bridges;vector<int>retained;array<int,16>fa;E cur;vector<vector<E>>ns;vector<unordered_set<uint64_t>>good;struct A{E f;vector<int>p;vector<vector<uint64_t>>spec;};vector<A>as;struct DSU{int adj[40][2]{},deg[40]{},comp[40];bool ok=true;DSU(){fill(comp,comp+40,-1);}void add(int a,int b){if(a==b||deg[a]>=2||deg[b]>=2){ok=false;return;}for(int k=0;k<deg[a];k++)if(adj[a][k]==b){ok=false;return;}adj[a][deg[a]++]=b;adj[b][deg[b]++]=a;}void prepare(){for(int start=0;start<40;start++)if(comp[start]<0){int stack[40],n=0,vertices=0,degrees=0;stack[n++]=start;comp[start]=start;while(n){int x=stack[--n];vertices++;degrees+=deg[x];for(int k=0;k<deg[x];k++){int y=adj[x][k];if(comp[y]<0){comp[y]=start;stack[n++]=y;}}}if(degrees/2>=vertices)ok=false;}}int rt(int x){return comp[x];}};ifstream expected;
long long total=0,bad=0;ofstream out;
void genN(unsigned m,int f){if(!m){ns[f].push_back(cur);return;}int a=__builtin_ctz(m);m^=1u<<a;for(int j=0;j<4;j++){int b=a^(1<<j);if(m>>b&1){cur.push_back({a,b});genN(m^(1u<<b),f);cur.pop_back();}}}
void assessA(){A a;for(int v=1;v<16;v++)if(v!=3&&v!=5&&v!=9){if(fa[v]<0)a.p.push_back(v);else if(fa[v]>v)a.f.push_back({v,fa[v]});}a.spec.resize(bridges.size());for(int f=0;f<(int)bridges.size();f++){set<uint64_t>ss;vector<int>ep=a.p;ep.insert(ep.end(),bridges[f].begin(),bridges[f].end());for(auto&N:ns[f]){DSU d;for(auto[x,y]:a.f)d.add(x,y);for(auto[x,y]:N)d.add(x,y);d.prepare();if(!d.ok)continue;uint64_t code=0;bool ok=true;for(int i=0;i<c+4;i++){int mate=-1;for(int j=0;j<c+4;j++)if(i!=j&&d.rt(ep[i])==d.rt(ep[j])){if(mate>=0)ok=false;mate=j;}if(mate<0)ok=false;else code|=uint64_t(mate)<<(4*i);}if(ok)ss.insert(code);}a.spec[f]=vector<uint64_t>(ss.begin(),ss.end());}as.push_back(move(a));}
void genA(unsigned m,int skip){if(!m){if(!skip)assessA();return;}int a=__builtin_ctz(m);m^=1u<<a;if(skip)genA(m,skip-1);for(int b=a+1;b<16;b++)if(m>>b&1){fa[a]=b;fa[b]=a;genA(m^(1u<<b),skip);fa[a]=fa[b]=-1;}}
bool works(A&a,E&F,vector<int>&bp){for(int f=0;f<(int)bridges.size();f++){int ep[16];for(int i=0;i<c;i++)ep[i]=bp[i];for(int i=0;i<4;i++)ep[c+i]=16+bridges[f][i];unsigned terminal=65532u;for(int z:bridges[f])terminal&=~(1u<<z);for(auto code:a.spec[f]){DSU d;for(auto[x,y]:F)d.add(x,y);for(int z:bridges[f])d.add(z,16+z);for(int i=0;i<c+4;i++){int j=(code>>(4*i))&15;if(j>i)d.add(ep[i],ep[j]);}d.prepare();if(!d.ok)continue;int first[40];fill(first,first+40,-1);uint64_t key=0;bool ok=true;for(int v=2;v<16;v++)if(terminal>>v&1){int r=d.rt(v);if(first[r]<0)first[r]=v;else if(first[r]>=16){ok=false;break;}else{int u=first[r];key|=uint64_t(u)<<(4*v);key|=uint64_t(v)<<(4*u);first[r]=16;}}if(ok&&good[f].count(key))return true;}}return false;}
int main(int argc,char**argv){if(argc!=2)return 2;c=stoi(argv[1]);int je[3]={6,10,12},jo[3]={7,11,13};for(int i=0;i<3;i++)for(int j=i+1;j<3;j++)for(int p=0;p<3;p++)for(int q=p+1;q<3;q++)for(int rev=0;rev<2;rev++){bridges.push_back({hs[i],hs[j],je[rev?q:p],jo[rev?p:q]});for(int u:hs)if(u!=hs[i]&&u!=hs[j])retained.push_back(u);}ns.resize(bridges.size());good.resize(bridges.size());for(int f=0;f<(int)bridges.size();f++){auto bs=bridges[f];int u=retained[f];for(int i=0;i<4;i++)for(int j=i+1;j<4;j++){int a=u^(1<<i),b=u^(1<<j);if(!a||!b||a==bs[2]||a==bs[3]||b==bs[2]||b==bs[3])continue;cur={{u,a},{u,b}};genN(65534u&~(1u<<u)&~(1u<<a)&~(1u<<b)&~(1u<<bs[2])&~(1u<<bs[3]),f);}cur.clear();string name="q4_five_avoided_";for(int z:bs)name+=to_string(z)+"_";name+="1.bin";ifstream in(name,ios::binary);unsigned char b[27];int n=0;while(in.read((char*)b,27)){n++;if(b[16]!=255){uint64_t key=0;for(int v=2;v<16;v++)if(b[v]!=255)key|=uint64_t(b[v])<<(4*v);good[f].insert(key);}}assert(n==945);}vector<int>order(bridges.size());iota(order.begin(),order.end(),0);stable_sort(order.begin(),order.end(),[](int a,int b){return good[a].size()>good[b].size();});auto oldb=bridges;auto oldn=ns;auto oldg=good;for(int i=0;i<(int)order.size();i++){bridges[i]=oldb[order[i]];ns[i]=move(oldn[order[i]]);good[i]=move(oldg[order[i]]);}fa.fill(-1);genA(65534u&~(1u<<3)&~(1u<<5)&~(1u<<9),c);cerr<<"A "<<as.size()<<" ready\n";ifstream in("t15_core1_route_B"+to_string(c)+".txt");expected.open("t15_core1_joint_fourbridge_c"+to_string(c)+"_residual_inputs.bin",ios::binary);assert(expected);int x,y,bi=0;while(in>>x>>y){E F={{x,y}};unsigned covered=(1u<<x)|(1u<<y);for(int j=1;j<(14-c)/2;j++){in>>x>>y;F.push_back({x,y});covered|=(1u<<x)|(1u<<y);}vector<int>bp;for(int v=2;v<16;v++)if(!(covered>>v&1))bp.push_back(v);do{for(auto&a:as){total++;if(!works(a,F,bp)){bad++;string raw;for(auto[u,v]:a.f){raw.push_back(char(2*u+1));raw.push_back(char(2*v+1));}for(auto[u,v]:F){raw.push_back(char(2*u));raw.push_back(char(2*v));}for(int j=0;j<c;j++){raw.push_back(char(2*a.p[j]+1));raw.push_back(char(2*bp[j]));}char saved[26];expected.read(saved,26);assert(expected.gcount()==26&&raw==string(saved,26));}}}while(next_permutation(bp.begin(),bp.end()));cerr<<"B "<<++bi<<" total "<<total<<" bad "<<bad<<"\n";}char trailing;assert(!expected.get(trailing));cout<<"{\"status\":\"PASS\",\"c\":"<<c<<",\"A\":"<<as.size()<<",\"B\":"<<bi<<",\"inputs\":"<<total<<",\"residual\":"<<bad<<"}\n";}
